
.setting-section {
  margin-bottom: 0.5rem;
  details {
    transition: all 0.5s ease;
  }

  summary {
    cursor: pointer;
    padding: 0.5rem;
    background: linear-gradient(135deg, rgba(43, 29, 14, 0.6) 0%, rgba(62, 42, 20, 0.4) 100%);
    border-radius: 0.4rem;
    color: var(--user-color-primary, #d4b16a);
    font-family: var(--font-title, 'ZCOOL XiaoWei', serif);
    font-size: 0.9rem;
    letter-spacing: 1px;
    transition: all 0.5s ease;
    list-style: none;
    display: flex;
    align-items: center;
    gap: 0.5rem;

    &::-webkit-details-marker {
      display: none;
    }

    &::before {
      content: '▶';
      font-size: 0.7rem;
      transition: transform 0.5s ease;
      color: var(--user-color-primary, #d4b16a);
    }

    &:hover {
      background: linear-gradient(135deg, rgba(43, 29, 14, 0.8) 0%, rgba(62, 42, 20, 0.6) 100%);
    }
  }

  &[open] summary::before {
    transform: rotate(90deg);
  }

  &[open] > summary {
    border-radius: 0.4rem 0.4rem 0 0;
    border-bottom: 1px solid rgba(165, 113, 58, 0.3);
  }

  .setting-content {
    padding: 0.75rem;
    background: rgba(43, 29, 14, 0.4);
    border-radius: 0 0 0.4rem 0.4rem;
    opacity: 0;
    transform: translateY(-10px);
    transition:
      opacity 0.5s ease,
      transform 0.5s ease;
  }
}

.setting-section[open] .setting-content {
  opacity: 1;
  transform: translateY(0);
}

.character-list-section {
  margin-top: 0.5rem;
}

.character-forms {
  overflow-y: auto;
  padding-right: 0.25rem;

  &::-webkit-scrollbar {
    width: 0.3rem;
  }

  &::-webkit-scrollbar-track {
    background: rgba(0, 0, 0, 0.2);
    border-radius: 0.15rem;
  }

  &::-webkit-scrollbar-thumb {
    background: rgba(165, 113, 58, 0.5);
    border-radius: 0.15rem;
  }
}

.character-form {
  background: rgba(43, 29, 14, 0.2);
  border: 1px solid rgba(165, 113, 58, 0.2);
  border-radius: 0.4rem;
  padding: 0.6rem;
  margin-bottom: 0.5rem;
  transition: all 0.5s ease;
  overflow: hidden;

  &:last-child {
    margin-bottom: 0;
  }
}

.form-header {
  margin-bottom: 0.5rem;

  > summary {
    cursor: pointer;
    padding: 0.5rem;
    background: linear-gradient(135deg, rgba(43, 29, 14, 0.6) 0%, rgba(62, 42, 20, 0.4) 100%);
    border-radius: 0.4rem;
    color: var(--user-color-primary, #d4b16a);
    font-family: var(--font-title, 'ZCOOL XiaoWei', serif);
    font-size: 0.9rem;
    letter-spacing: 1px;
    transition: all 0.5s ease;
    list-style: none;
    display: flex;
    align-items: center;
    gap: 0.5rem;

    &::-webkit-details-marker {
      display: none;
    }

    &::before {
      content: '▶';
      font-size: 0.7rem;
      transition: transform 0.5s ease;
      color: var(--user-color-primary, #d4b16a);
    }

    &:hover {
      background: linear-gradient(135deg, rgba(43, 29, 14, 0.8) 0%, rgba(62, 42, 20, 0.6) 100%);
    }
  }

  &[open] > summary::before {
    transform: rotate(90deg);
  }
}

.form-body {
  padding-top: 0.5rem;
}

.form-section-title {
  font-size: 0.75rem;
  color: var(--user-color-primary, #d4b16a);
  font-family: var(--font-title, 'ZCOOL XiaoWei', serif);
  margin: 0.75rem 0 0.5rem 0;
  padding-bottom: 0.25rem;
  border-bottom: 1px solid rgba(165, 113, 58, 0.3);

  &:first-of-type {
    margin-top: 0;
  }
}

.form-title {
  font-family: var(--font-title, 'ZCOOL XiaoWei', serif);
  font-size: 0.9rem;
  color: var(--user-color-primary, #d4b16a);
}

.form-row {
  display: flex;
  align-items: center;
  margin-bottom: 0.35rem;
  font-size: 0.75rem;

  &:last-child {
    margin-bottom: 0;
  }

  label {
    color: var(--text-secondary, #b8a98f);
    min-width: 3.5rem;
  }

  input,
  select {
    flex: 1;
    background: rgba(0, 0, 0, 0.3);
    border: 1px solid rgba(165, 113, 58, 0.3);
    border-radius: 0.25rem;
    padding: 0.25rem 0.4rem;
    font-size: 0.75rem;
    color: var(--text-primary, #f0e6d3);
    font-family: inherit;

    &:focus {
      outline: none;
      border-color: rgba(212, 177, 106, 0.8);
    }
  }

  input[type='number'] {
    max-width: 5rem;
  }
}

.action-btn {
  padding: 0.5rem 1rem;
  background: linear-gradient(135deg, rgba(212, 177, 106, 0.2) 0%, rgba(212, 177, 106, 0.1) 100%);
  border: 1px solid rgba(212, 177, 106, 0.5);
  border-radius: 0.4rem;
  color: var(--text-primary, #f0e6d3);
  font-family: var(--font-serif, 'Noto Serif SC', serif);
  font-size: 0.8rem;
  cursor: pointer;
  transition: all 0.3s ease;

  &:hover {
    background: linear-gradient(135deg, rgba(212, 177, 106, 0.3) 0%, rgba(212, 177, 106, 0.2) 100%);
    border-color: rgba(212, 177, 106, 0.8);
    transform: translateY(-1px);
  }

  &:active {
    transform: translateY(0);
  }
}

.no-data {
  color: var(--text-secondary, #b8a98f);
  font-size: 0.8rem;
  text-align: center;
  padding: 1rem;
}

.modal-overlay {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.7);
  z-index: 1000;
  align-items: center;
  justify-content: center;
  animation: fadeIn 0.3s ease-out;

  &.active {
    display: flex;
  }
}

.modal-content {
  background: linear-gradient(135deg, rgba(43, 29, 14, 0.98) 0%, rgba(62, 42, 20, 0.95) 100%);
  border: 1px solid var(--border-color);
  border-radius: 0.75rem;
  width: 90%;
  max-width: 400px;
  padding: 0;
  box-shadow:
    0 8px 32px rgba(0, 0, 0, 0.5),
    inset 0 1px 0 rgba(212, 177, 106, 0.1);
  animation: slideIn 0.3s ease-out;
}

.modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--border-color);
  background: linear-gradient(90deg, rgba(212, 177, 106, 0.1) 0%, transparent 100%);

  h3 {
    margin: 0;
    font-family: var(--font-title);
    font-size: 1.1rem;
    color: var(--text-title);
    letter-spacing: 2px;
  }
}

.modal-close {
  width: 1.5rem;
  height: 1.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--text-secondary);
  font-size: 1rem;
  border-radius: 0.25rem;
  transition: all 0.2s ease;

  &:hover {
    background-color: rgba(255, 107, 107, 0.2);
    color: #ff6b6b;
  }
}

.modal-body {
  padding: 1rem;

  p {
    margin: 0;
    color: var(--text-primary);
    line-height: 1.5;
  }
}

.modal-footer {
  display: flex;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  border-top: 1px solid var(--border-color);
  background: linear-gradient(90deg, rgba(212, 177, 106, 0.05) 0%, transparent 100%);
}

.modal-btn {
  padding: 0.5rem 1rem;
  border: 1px solid var(--border-color);
  border-radius: 0.25rem;
  cursor: pointer;
  font-size: 0.85rem;
  transition: all 0.2s ease;
  background: transparent;
  color: var(--text-primary);

  &:hover {
    background: rgba(212, 177, 106, 0.1);
  }
}

.cancel-btn {
  &:hover {
    background: rgba(255, 107, 107, 0.2);
    color: #ff6b6b;
  }
}

.confirm-btn {
  background: rgba(212, 177, 106, 0.2);
  border-color: var(--border-color);

  &:hover {
    background: rgba(212, 177, 106, 0.3);
  }
}

.info-group {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.5rem;
}

.info-item {
  display: flex;
  flex-direction: column;
  background: rgba(0, 0, 0, 0.2);
  border-radius: 0.25rem;
  padding: 0.4rem;

  &.hidden {
    display: none;
  }
}

.info-label {
  font-size: 0.7rem;
  color: var(--text-secondary, #b8a98f);
  margin-bottom: 0.2rem;
}

.info-value {
  font-size: 0.75rem;
  color: var(--text-primary, #f0e6d3);
}

.form-section {
  margin-top: 0.75rem;
  padding-top: 0.5rem;
  border-top: 1px solid rgba(165, 113, 58, 0.3);
}

.martial-arts-container {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
}

.martial-art-item {
  background: rgba(165, 113, 58, 0.2);
  border: 1px solid rgba(165, 113, 58, 0.3);
  border-radius: 0.25rem;
  padding: 0.2rem 0.4rem;
  font-size: 0.7rem;
  color: var(--text-primary, #f0e6d3);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.skill-text {
  flex: 1;
  word-break: break-all;
  background: transparent;
  border: none;
  color: var(--text-primary, #f0e6d3);
  font-size: inherit;
  font-family: inherit;
  resize: none;
  padding: 0;
  min-height: 1.2em;

  &:focus {
    outline: none;
  }

  &::placeholder {
    color: rgba(184, 169, 143, 0.5);
  }
}

.delete-icon {
  color: rgba(255, 100, 100, 0.7);
  cursor: pointer;
  margin-left: 0.5rem;
  font-size: 0.8rem;
  transition: color 0.2s;

  &:hover {
    color: rgba(255, 80, 80, 1);
  }
}

.add-icon {
  color: rgba(100, 200, 100, 0.7);
  cursor: pointer;
  margin-left: 0.5rem;
  font-size: 0.8rem;
  transition: color 0.2s;

  &:hover {
    color: rgba(100, 200, 100, 1);
  }
}

.form-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.5rem;
  border-top: 1px solid rgba(165, 113, 58, 0.3);
  margin-top: 0.5rem;
}

.action-left {
  display: flex;
  gap: 0.5rem;
}

.action-right {
  display: flex;
}

.action-btn {
  display: flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.3rem 0.6rem;
  border: 1px solid rgba(165, 113, 58, 0.5);
  border-radius: 0.25rem;
  background: rgba(165, 113, 58, 0.2);
  color: var(--text-primary, #f0e6d3);
  font-size: 0.75rem;
  cursor: pointer;
  transition: all 0.2s;

  &:hover {
    background: rgba(165, 113, 58, 0.4);
  }
}

.save-btn {
  &:hover {
    background: rgba(100, 150, 255, 0.3);
    border-color: rgba(100, 150, 255, 0.5);
  }
}

.add-btn {
  background: rgba(100, 200, 100, 0.2);
  border-color: rgba(100, 200, 100, 0.5);

  &:hover {
    background: rgba(100, 200, 100, 0.4);
  }
}

.value-input {
  width: 100%;
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid rgba(165, 113, 58, 0.3);
  border-radius: 0.25rem;
  padding: 0.25rem 0.4rem;
  font-size: 0.75rem;
  color: var(--text-primary, #f0e6d3);
  font-family: inherit;
  resize: none;

  &:focus {
    outline: none;
    border-color: rgba(212, 177, 106, 0.8);
  }

  &::placeholder {
    color: rgba(184, 169, 143, 0.5);
  }
}

.value-textarea {
  min-height: 3rem;
}

.full-width {
  grid-column: 1 / -1;
}
